// Reports Page
// View daily, monthly, and yearly sales reports

import React, { useState, useEffect } from 'react';
import { FaChartLine, FaCalendarDay, FaCalendarAlt, FaCalendar, FaPrint, FaFileExport, FaRupeeSign, FaFileInvoice } from 'react-icons/fa';
import { toast } from 'react-toastify';
import Loader from '../components/common/Loader';
import { getReports } from '../services/reportService';

const Reports = () => {
  const [loading, setLoading] = useState(false);
  const [reportType, setReportType] = useState('daily'); // daily, monthly, yearly
  const [reportData, setReportData] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedMonth, setSelectedMonth] = useState(new Date().getMonth() + 1);
  const [selectedYear, setSelectedYear] = useState(new Date().getFullYear());

  useEffect(() => {
    fetchReport();
  }, [reportType, selectedDate, selectedMonth, selectedYear]);

  const fetchReport = async () => {
    setLoading(true);
    try {
      let data;
      if (reportType === 'daily') {
        data = await getReports.daily(selectedDate);
      } else if (reportType === 'monthly') {
        data = await getReports.monthly(selectedYear, selectedMonth);
      } else if (reportType === 'yearly') {
        data = await getReports.yearly(selectedYear);
      }
      setReportData(data);
    } catch (error) {
      console.error('Error fetching report:', error);
      toast.error('Failed to load report');
    } finally {
      setLoading(false);
    }
  };

  const exportReport = () => {
    toast.info('Export feature coming soon!');
  };

  const printReport = () => {
    window.print();
  };

  return (
    <>
      {/* Print-specific styles */}
      <style>{`
        @media print {
          /* Hide everything except report content */
          body * {
            visibility: hidden;
          }
          
          /* Show only the printable area */
          .printable-area,
          .printable-area * {
            visibility: visible;
          }
          
          .printable-area {
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
          }
          
          /* Hide non-printable elements */
          .no-print {
            display: none !important;
          }
          
          /* Adjust page margins */
          @page {
            margin: 1cm;
          }
          
          /* Ensure proper page breaks */
          .page-break {
            page-break-after: always;
          }
        }
      `}</style>

      <div className="p-6">
      {/* Header */}
      <div className="mb-8 no-print">
        <h1 className="text-3xl font-bold text-gray-800 mb-2 flex items-center">
          <FaChartLine className="mr-3 text-purple-600" />
          Sales Reports
        </h1>
        <p className="text-gray-600">View and analyze your sales performance</p>
      </div>

      {/* Report Type Selector */}
      <div className="bg-white rounded-2xl shadow-lg p-6 mb-6 no-print">
        <div className="flex flex-wrap gap-4 items-center justify-between">
          {/* Report Type Buttons */}
          <div className="flex gap-2">
            <button
              onClick={() => setReportType('daily')}
              className={`px-6 py-3 rounded-xl font-semibold transition-all duration-200 flex items-center gap-2 ${
                reportType === 'daily'
                  ? 'bg-gradient-to-r from-purple-500 to-pink-600 text-white shadow-lg'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <FaCalendarDay />
              Daily
            </button>
            <button
              onClick={() => setReportType('monthly')}
              className={`px-6 py-3 rounded-xl font-semibold transition-all duration-200 flex items-center gap-2 ${
                reportType === 'monthly'
                  ? 'bg-gradient-to-r from-purple-500 to-pink-600 text-white shadow-lg'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <FaCalendarAlt />
              Monthly
            </button>
            <button
              onClick={() => setReportType('yearly')}
              className={`px-6 py-3 rounded-xl font-semibold transition-all duration-200 flex items-center gap-2 ${
                reportType === 'yearly'
                  ? 'bg-gradient-to-r from-purple-500 to-pink-600 text-white shadow-lg'
                  : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
              }`}
            >
              <FaCalendar />
              Yearly
            </button>
          </div>

          {/* Date Selectors */}
          <div className="flex gap-3">
            {reportType === 'daily' && (
              <input
                type="date"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent"
              />
            )}
            {reportType === 'monthly' && (
              <>
                <select
                  value={selectedMonth}
                  onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent"
                >
                  {Array.from({ length: 12 }, (_, i) => (
                    <option key={i + 1} value={i + 1}>
                      {new Date(2000, i).toLocaleString('default', { month: 'long' })}
                    </option>
                  ))}
                </select>
                <input
                  type="number"
                  value={selectedYear}
                  onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                  min="2020"
                  max="2030"
                  className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent w-24"
                />
              </>
            )}
            {reportType === 'yearly' && (
              <input
                type="number"
                value={selectedYear}
                onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                min="2020"
                max="2030"
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-emerald-500 focus:border-transparent w-24"
              />
            )}
          </div>

          {/* Action Buttons */}
          <div className="flex gap-2">
            <button
              onClick={printReport}
              className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition-colors flex items-center gap-2"
            >
              <FaDownload />
              Print
            </button>
            <button
              onClick={exportReport}
              className="px-4 py-2 bg-green-500 text-white rounded-lg hover:bg-green-600 transition-colors flex items-center gap-2"
            >
              <FaFileExport />
              Export
            </button>
          </div>
        </div>
      </div>

      {/* Report Content */}
      {loading ? (
        <Loader />
      ) : reportData ? (
        <div className="space-y-6 printable-area">
          {/* Summary Cards */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-gradient-to-br from-purple-500 to-pink-600 rounded-2xl shadow-lg p-6 text-white">
              <div className="flex items-center justify-between mb-2">
                <h3 className="text-lg font-semibold opacity-90">Total Sales</h3>
                <FaChartLine className="text-3xl opacity-80" />
              </div>
              <p className="text-4xl font-bold">
                ₹{reportData.data?.summary?.totalSales?.toLocaleString() || 0}
              </p>
              <p className="text-sm opacity-80 mt-2">
                {reportType === 'daily' && 'Today'}
                {reportType === 'monthly' && 'This Month'}
                {reportType === 'yearly' && 'This Year'}
              </p>
            </div>

            <div className="bg-gradient-to-br from-blue-500 to-indigo-600 rounded-2xl shadow-lg p-6 text-white">
              <div className="flex items-center justify-between mb-2">
                <h3 className="text-lg font-semibold opacity-90">Total Invoices</h3>
                <FaCalendarAlt className="text-3xl opacity-80" />
              </div>
              <p className="text-4xl font-bold">
                {reportData.data?.summary?.totalInvoices || 0}
              </p>
              <p className="text-sm opacity-80 mt-2">Invoices generated</p>
            </div>

            <div className="bg-gradient-to-br from-purple-500 to-pink-600 rounded-2xl shadow-lg p-6 text-white">
              <div className="flex items-center justify-between mb-2">
                <h3 className="text-lg font-semibold opacity-90">Average Sale</h3>
                <FaChartLine className="text-3xl opacity-80" />
              </div>
              <p className="text-4xl font-bold">
                ₹{(reportData.data?.summary?.totalSales / (reportData.data?.summary?.totalInvoices || 1)).toFixed(2)}
              </p>
              <p className="text-sm opacity-80 mt-2">Per invoice</p>
            </div>
          </div>

          {/* Chart/Graph Section */}
          <div className="bg-white rounded-2xl shadow-lg p-6">
            <h2 className="text-2xl font-bold text-gray-800 mb-6">
              {reportType === 'daily' && 'Sales by Hour'}
              {reportType === 'monthly' && 'Sales by Day'}
              {reportType === 'yearly' && 'Sales by Month'}
            </h2>

            {/* Simple Bar Chart */}
            <div className="space-y-3">
              {reportType === 'daily' &&
                reportData.data?.salesByHour
                  ?.filter((item) => item.sales > 0)
                  .map((item) => (
                    <div key={item.hour} className="flex items-center gap-4">
                      <div className="w-20 text-sm font-semibold text-gray-600">
                        {item.hour}:00
                      </div>
                      <div className="flex-1 bg-gray-100 rounded-lg overflow-hidden">
                        <div
                          className="bg-gradient-to-r from-purple-500 to-pink-600 h-10 flex items-center justify-end px-4 text-white font-semibold transition-all duration-500"
                          style={{
                            width: `${(item.sales / Math.max(...reportData.data.salesByHour.map((h) => h.sales))) * 100}%`,
                          }}
                        >
                          ₹{item.sales.toLocaleString()}
                        </div>
                      </div>
                      <div className="w-20 text-sm text-gray-600">
                        {item.invoices} bills
                      </div>
                    </div>
                  ))}

              {reportType === 'monthly' &&
                reportData.data?.salesByDay
                  ?.filter((item) => item.sales > 0)
                  .map((item) => (
                    <div key={item.day} className="flex items-center gap-4">
                      <div className="w-20 text-sm font-semibold text-gray-600">
                        Day {item.day}
                      </div>
                      <div className="flex-1 bg-gray-100 rounded-lg overflow-hidden">
                        <div
                          className="bg-gradient-to-r from-blue-500 to-indigo-600 h-10 flex items-center justify-end px-4 text-white font-semibold transition-all duration-500"
                          style={{
                            width: `${(item.sales / Math.max(...reportData.data.salesByDay.map((d) => d.sales))) * 100}%`,
                          }}
                        >
                          ₹{item.sales.toLocaleString()}
                        </div>
                      </div>
                      <div className="w-20 text-sm text-gray-600">
                        {item.invoices} bills
                      </div>
                    </div>
                  ))}

              {reportType === 'yearly' &&
                reportData.data?.salesByMonth
                  ?.filter((item) => item.sales > 0)
                  .map((item) => (
                    <div key={item.month} className="flex items-center gap-4">
                      <div className="w-20 text-sm font-semibold text-gray-600">
                        {new Date(2000, item.month - 1).toLocaleString('default', { month: 'short' })}
                      </div>
                      <div className="flex-1 bg-gray-100 rounded-lg overflow-hidden">
                        <div
                          className="bg-gradient-to-r from-purple-500 to-pink-600 h-10 flex items-center justify-end px-4 text-white font-semibold transition-all duration-500"
                          style={{
                            width: `${(item.sales / Math.max(...reportData.data.salesByMonth.map((m) => m.sales))) * 100}%`,
                          }}
                        >
                          ₹{item.sales.toLocaleString()}
                        </div>
                      </div>
                      <div className="w-20 text-sm text-gray-600">
                        {item.invoices} bills
                      </div>
                    </div>
                  ))}
            </div>

            {/* No Data Message */}
            {((reportType === 'daily' && reportData.data?.salesByHour?.every((h) => h.sales === 0)) ||
              (reportType === 'monthly' && reportData.data?.salesByDay?.every((d) => d.sales === 0)) ||
              (reportType === 'yearly' && reportData.data?.salesByMonth?.every((m) => m.sales === 0))) && (
              <div className="text-center py-12 text-gray-500">
                <FaChartLine className="text-6xl mx-auto mb-4 opacity-30" />
                <p className="text-xl font-semibold">No sales data available</p>
                <p className="text-sm mt-2">Start creating invoices to see reports</p>
              </div>
            )}
          </div>

          {/* Recent Invoices */}
          {reportData.data?.invoices && reportData.data.invoices.length > 0 && (
            <div className="bg-white rounded-2xl shadow-lg p-6">
              <h2 className="text-2xl font-bold text-gray-800 mb-6">Recent Invoices</h2>
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b-2 border-gray-200">
                      <th className="text-left py-3 px-4 font-semibold text-gray-700">Invoice #</th>
                      <th className="text-left py-3 px-4 font-semibold text-gray-700">Customer</th>
                      <th className="text-left py-3 px-4 font-semibold text-gray-700">Date</th>
                      <th className="text-right py-3 px-4 font-semibold text-gray-700">Amount</th>
                    </tr>
                  </thead>
                  <tbody>
                    {reportData.data.invoices.slice(0, 10).map((invoice) => (
                      <tr key={invoice.id} className="border-b border-gray-100 hover:bg-gray-50">
                        <td className="py-3 px-4 font-medium text-purple-600">
                          {invoice.invoiceNumber}
                        </td>
                        <td className="py-3 px-4">{invoice.customerName}</td>
                        <td className="py-3 px-4 text-gray-600">
                          {new Date(invoice.createdAt).toLocaleDateString()}
                        </td>
                        <td className="py-3 px-4 text-right font-semibold">
                          ₹{parseFloat(invoice.total).toLocaleString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-lg p-12 text-center">
          <FaChartLine className="text-6xl text-gray-300 mx-auto mb-4" />
          <p className="text-xl text-gray-500">No report data available</p>
        </div>
      )}
    </div>
    </>
  );
};

export default Reports;
